import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Connectors","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/claude/connectors.md","filePath":"products/ai-coding/claude/connectors.md","lastUpdated":1787044708000}'),r={name:"products/ai-coding/claude/connectors.md"};function s(i,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h1><blockquote><p>Connectors let Claude connect directly to your apps and services—reading data, executing actions, triggering workflows—all within conversation, without switching tools. This is the core capability that elevates Claude from &quot;Q&amp;A assistant&quot; to &quot;execution agent.&quot;</p></blockquote><h2 id="what-are-connectors" tabindex="-1">What Are Connectors <a class="header-anchor" href="#what-are-connectors" aria-label="Permalink to &quot;What Are Connectors&quot;">​</a></h2><p>A Connector is an authorization channel between Claude and an external service. Once connected, you can ask Claude directly in conversation to:</p><ul><li>Search emails and draft replies in Gmail</li><li>Check availability and create meetings in Google Calendar</li><li>Create or update pages in Notion</li><li>File issues and view PRs in Linear / GitHub</li><li>Send messages and search history in Slack</li></ul><p><strong>Underlying implementation</strong>: Connectors are built on <a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">Remote MCP (Model Context Protocol)</a>. Each connector is essentially an MCP server running in the cloud, exposing a set of tools to Claude.</p><p><strong>Availability</strong>: claude.ai web version, iOS/Android App, Claude Desktop (Cowork and Code tabs), Claude Code CLI, API.</p><hr><h2 id="connector-types" tabindex="-1">Connector Types <a class="header-anchor" href="#connector-types" aria-label="Permalink to &quot;Connector Types&quot;">​</a></h2><h3 id="pre-built-connectors" tabindex="-1">Pre-built Connectors <a class="header-anchor" href="#pre-built-connectors" aria-label="Permalink to &quot;Pre-built Connectors&quot;">​</a></h3><p>Officially built-in, one-click authorization, ready to use. 50+ connectors available, covering these categories:</p><table tabindex="0"><thead><tr><th>Category</th><th>Representative Services</th><th>Core Capabilities</th></tr></thead><tbody><tr><td><strong>Google Workspace</strong></td><td>Gmail, Google Calendar, Google Drive</td><td>Read emails/draft, check schedule/create meetings, search files</td></tr><tr><td><strong>Microsoft 365</strong></td><td>Outlook, Teams, SharePoint, OneDrive</td><td>Search emails/docs, view meetings, browse Teams messages</td></tr><tr><td><strong>Project Management</strong></td><td>Linear, Asana, Jira, Notion</td><td>Create/query issues, update tasks, search pages</td></tr><tr><td><strong>Code Hosting</strong></td><td>GitHub</td><td>View PRs, search code, create issues</td></tr><tr><td><strong>Communication</strong></td><td>Slack</td><td>Send messages, search history, read channels</td></tr><tr><td><strong>Design Tools</strong></td><td>Canva, Figma</td><td>View design files (some support interactive rendering)</td></tr><tr><td><strong>CRM / Sales</strong></td><td>Salesforce, HubSpot</td><td>Query records, update contacts</td></tr></tbody></table><blockquote><p><strong>Interactive marker</strong>: Some connectors support rendering dynamic interfaces directly in conversation (kanban boards, dashboards, design previews), not just text responses.</p></blockquote><h3 id="custom-connectors-remote-mcp" tabindex="-1">Custom Connectors (Remote MCP) <a class="header-anchor" href="#custom-connectors-remote-mcp" aria-label="Permalink to &quot;Custom Connectors (Remote MCP)&quot;">​</a></h3><p>If your tool doesn&#39;t have a pre-built connector, you can build one yourself:</p><ol><li>Develop an MCP protocol-compliant server (supports HTTP + SSE)</li><li>Deploy to a <strong>publicly accessible</strong> address (Anthropic cloud needs to reach it)</li><li>Enter your MCP Server URL and OAuth credentials in Claude settings</li><li>Use your custom tools in conversation</li></ol><blockquote><p>For internal services, add Anthropic&#39;s egress IPs to your firewall whitelist. See <a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">Remote MCP development docs</a>.</p></blockquote><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="step-1-open-the-connectors-directory" tabindex="-1">Step 1: Open the Connectors Directory <a class="header-anchor" href="#step-1-open-the-connectors-directory" aria-label="Permalink to &quot;Step 1: Open the Connectors Directory&quot;">​</a></h3><p><strong>Path A (In conversation)</strong>: Click the <strong><code>+</code></strong> button at the bottom-left of the conversation → Select <strong>Connectors</strong></p><p><strong>Path B (Settings page)</strong>: <code>Settings → Customize → Connectors</code> → Browse directory</p><h3 id="step-2-connect-a-service" tabindex="-1">Step 2: Connect a Service <a class="header-anchor" href="#step-2-connect-a-service" aria-label="Permalink to &quot;Step 2: Connect a Service&quot;">​</a></h3><ol><li>Find your target connector, click to view its capabilities and read/write permissions</li><li>Click <strong>Connect</strong> (for pre-built) or <strong>Install</strong> (for remote MCP)</li><li>Complete the OAuth authorization flow (redirects to the service&#39;s login page)</li><li>After authorization, the connector appears in your installed list</li></ol><h3 id="step-3-enable-in-conversations" tabindex="-1">Step 3: Enable in Conversations <a class="header-anchor" href="#step-3-enable-in-conversations" aria-label="Permalink to &quot;Step 3: Enable in Conversations&quot;">​</a></h3><p>Installed connectors <strong>won&#39;t automatically activate in all conversations</strong>. In conversations where you want to use them:</p><ul><li>Click the <strong><code>+</code></strong> button and check the connectors to enable</li><li>Or just describe your task—Claude will prompt you to enable relevant connectors</li></ul><h3 id="step-4-just-describe-your-task" tabindex="-1">Step 4: Just Describe Your Task <a class="header-anchor" href="#step-4-just-describe-your-task" aria-label="Permalink to &quot;Step 4: Just Describe Your Task&quot;">​</a></h3><p>With connectors activated, simply express your needs in natural language:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me check emails from acme.com in Gmail this week,</span></span>
<span class="line"><span>extract all content mentioning delivery dates,</span></span>
<span class="line"><span>then create an &quot;Acme Follow-up&quot; page in Notion to record them.</span></span></code></pre></div><p>Claude will automatically call the Gmail connector to search emails, then call the Notion connector to create the page.</p><hr><h2 id="key-connectors-in-detail" tabindex="-1">Key Connectors in Detail <a class="header-anchor" href="#key-connectors-in-detail" aria-label="Permalink to &quot;Key Connectors in Detail&quot;">​</a></h2><h3 id="google-workspace" tabindex="-1">Google Workspace <a class="header-anchor" href="#google-workspace" aria-label="Permalink to &quot;Google Workspace&quot;">​</a></h3><p><strong>Gmail</strong></p><ul><li>Search emails using natural language (&quot;emails from Alice about budget last week&quot;)</li><li>Draft emails (Claude generates drafts, <strong>you must manually send</strong>—Claude cannot send on your behalf)</li><li>Read attachment info, manage labels and threads</li><li>List saved drafts</li></ul><p><strong>Google Calendar</strong></p><ul><li>View events on personal and shared calendars</li><li>Create, edit, delete events with support for recurrence rules</li><li>Find common availability across multiple participants</li><li>Manage attendee lists, respond to invitations</li></ul><p><strong>Google Drive</strong></p><ul><li>Search and retrieve document content (text extraction only, doesn&#39;t process images)</li><li>Add documents to current conversation or Project</li><li>View file permissions and recent changes</li><li>Save Claude-generated files directly to Drive (requires code execution enabled)</li></ul><h3 id="microsoft-365" tabindex="-1">Microsoft 365 <a class="header-anchor" href="#microsoft-365" aria-label="Permalink to &quot;Microsoft 365&quot;">​</a></h3><p><strong>Read-only access</strong>—Claude can retrieve and analyze, but <strong>cannot modify, delete, or create</strong> content:</p><ul><li><strong>Outlook</strong>: Search email threads, track project progress and customer feedback</li><li><strong>Teams</strong>: Read channel messages and chat history you participate in</li><li><strong>SharePoint / OneDrive</strong>: Cross-site search and analyze documents</li><li><strong>Calendar</strong>: Read meeting summaries and attendee info, prepare for upcoming meetings</li></ul><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><ul><li>Search code repositories, view file contents</li><li>Create issues, view PR status and comments</li><li>Search commit history</li></ul><blockquote><p>Note for Claude Code users: In CLI, connecting GitHub via MCP offers more features, including write operations like creating PRs and merging.</p></blockquote><h3 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h3><ul><li>Search channel message history</li><li>Send messages to specified channels or DMs (<strong>requires your confirmation before execution</strong>)</li><li>Read thread replies</li></ul><h3 id="linear-asana-jira" tabindex="-1">Linear / Asana / Jira <a class="header-anchor" href="#linear-asana-jira" aria-label="Permalink to &quot;Linear / Asana / Jira&quot;">​</a></h3><ul><li>Create, query, update issues and tasks</li><li>Search project boards</li><li>Get sprint status</li></ul><hr><h2 id="combining-connectors-with-projects" tabindex="-1">Combining Connectors with Projects <a class="header-anchor" href="#combining-connectors-with-projects" aria-label="Permalink to &quot;Combining Connectors with Projects&quot;">​</a></h2><p>Connectors work best when used within <strong>Projects</strong>:</p><ol><li>Connect Google Drive in a Project—Claude can continuously access all documents for that project</li><li>Connect Linear in a Project—Claude remembers the project&#39;s issue conventions and priority standards</li><li>Combine with Project custom instructions for unified workflow standards</li></ol><p><strong>Example</strong>: Create a &quot;Q2 Product Planning&quot; Project, connect Google Drive (requirement docs) + Linear (task management), making Claude a project assistant that can read requirements and sync task creation simultaneously.</p><hr><h2 id="connectors-scheduled-tasks" tabindex="-1">Connectors + Scheduled Tasks <a class="header-anchor" href="#connectors-scheduled-tasks" aria-label="Permalink to &quot;Connectors + Scheduled Tasks&quot;">​</a></h2><p>Connectors can work with <a href="./cowork.html#scheduled-task-automation">scheduled tasks</a> for automated workflows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every Monday at 9 AM:</span></span>
<span class="line"><span>- Read customer emails from last week in Gmail (Gmail connector)</span></span>
<span class="line"><span>- Summarize key issues and pending items</span></span>
<span class="line"><span>- Create &quot;Customer Weekly Report&quot; page in Notion (Notion connector)</span></span>
<span class="line"><span>- Send Slack notification to team (Slack connector)</span></span></code></pre></div><p>Cloud scheduled tasks (created via <code>/schedule</code>) carry your authorized connector permissions and don&#39;t require your computer to be on.</p><hr><h2 id="permissions-and-security" tabindex="-1">Permissions and Security <a class="header-anchor" href="#permissions-and-security" aria-label="Permalink to &quot;Permissions and Security&quot;">​</a></h2><h3 id="permission-model" tabindex="-1">Permission Model <a class="header-anchor" href="#permission-model" aria-label="Permalink to &quot;Permission Model&quot;">​</a></h3><ul><li><strong>Each connector independently authorized</strong>: Connecting Gmail doesn&#39;t mean authorizing Calendar—each service has separate OAuth</li><li><strong>Principle of least privilege</strong>: Claude can only access content you have permission to access in your account</li><li><strong>Read/write distinction</strong>: Connector detail pages clearly mark which operations are read-only and which write data</li><li><strong>Confirmation before action</strong>: For write operations (send messages, create issues, modify calendar), Claude shows the action plan and waits for your confirmation</li></ul><h3 id="notes-for-teams-and-enterprises" tabindex="-1">Notes for Teams and Enterprises <a class="header-anchor" href="#notes-for-teams-and-enterprises" aria-label="Permalink to &quot;Notes for Teams and Enterprises&quot;">​</a></h3><ul><li><strong>Team / Enterprise plans</strong>: Organization owners must first enable Connectors in <strong>Organization Settings</strong> before members can authorize and use them</li><li><strong>Data transfer</strong>: All connector data transfers are encrypted</li><li><strong>Disconnect</strong>: Revoke service authorization anytime in <code>Settings → Connectors</code></li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li>Periodically review connected services and disconnect unused connectors</li><li>Don&#39;t enable connectors with personal email in shared Projects (other members may trigger queries)</li><li>For services with sensitive data (like financial systems), use a dedicated account rather than your personal primary account for authorization</li></ul><hr><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q: Do Connectors cost extra?</strong></p><p>No. Connectors are included in Pro (and above) subscriptions at no additional cost.</p><p><strong>Q: Can connectors access all my data in a service?</strong></p><p>Only data you have permission to access. After connecting Google Drive, Claude can only read files you have access to—it cannot bypass the original service&#39;s permission controls.</p><p><strong>Q: Will Claude automatically operate my services without my knowledge?</strong></p><p>No. For write operations (draft emails, create events, send Slack messages), Claude will present an action plan and wait for your confirmation before executing.</p><p><strong>Q: Can my company&#39;s internal systems use Connectors?</strong></p><p>Yes, via custom Remote MCP, but your MCP server must be publicly accessible (or add Anthropic egress IPs to your whitelist).</p><p><strong>Q: How do I use connectors in Claude Code CLI?</strong></p><p>Claude Code connects tools via MCP integration (<code>claude mcp add</code>). This is a different entry point than the claude.ai Connectors UI, but the underlying protocol is the same. See <a href="./claude-code.html#mcp-integration">MCP Integration chapter</a>.</p><hr><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://support.claude.com/en/articles/10168395-set-up-claude-integrations" target="_blank" rel="noreferrer">Connector Setup Guide</a></li><li><a href="https://support.claude.com/en/articles/10166901-use-google-workspace-connectors" target="_blank" rel="noreferrer">Google Workspace Connector</a></li><li><a href="https://support.claude.com/en/articles/12542951-enable-and-use-the-microsoft-365-connector" target="_blank" rel="noreferrer">Microsoft 365 Connector</a></li><li><a href="https://support.claude.com/en/articles/11175166-get-started-with-custom-connectors-using-remote-mcp" target="_blank" rel="noreferrer">Custom Remote MCP Connector</a></li><li><a href="https://support.claude.com/en/articles/11176164-pre-built-web-connectors-using-remote-mcp" target="_blank" rel="noreferrer">Pre-built Web Connector List</a></li><li><a href="https://support.claude.com/en/collections/15399129-connectors" target="_blank" rel="noreferrer">Connectors Full Collection</a></li></ul>`,83)])])}const C=t(r,[["render",s]]);export{b as __pageData,C as default};
